subtitle.moveTo([-3.55, 2.72, 0]);
scene.add(title, subtitle);

const origin = [-0.7, -0.3, 0];
const unit = 0.78;
let t = 1;
function point(x, y, amount = t) {
  return [origin[0] + unit * ((1 + amount) * x + amount * y), origin[1] + unit * y, 0];
}
function segment(a, b, color, width) {
  const p = new Polygon({ vertices: [a, b], color });
  p.setFillOpacity(0);
  p.setStrokeWidth(width);
  return p;
}

const grid = [];
for (let x = -2; x <= 2; x += 0.5) {
  const line = segment(point(x, -2), point(x, 2), x === 0 ? GRAY : BLUE_E, x === 0 ? 2 : 1);
  grid.push({ line, a: [x, -2], b: [x, 2] });
  scene.add(line);
}
for (let y = -2; y <= 2; y += 0.5) {
  const line = segment(point(-2, y), point(2, y), y === 0 ? GRAY : BLUE_E, y === 0 ? 2 : 1);
  grid.push({ line, a: [-2, y], b: [2, y] });
  scene.add(line);
}

const original = new Polygon({ vertices: [point(0, 0, 0), point(1, 0, 0), point(1, 1, 0), point(0, 1, 0)], color: WHITE });
original.setFill(GRAY, 0.08);
original.setStrokeWidth(2);
const mapped = new Polygon({ vertices: [point(0, 0), point(1, 0), point(1, 1), point(0, 1)], color: BLUE });
mapped.setFill(BLUE, 0.28);
mapped.setStrokeWidth(3);
const basisX = segment(point(0, 0), point(1, 0), YELLOW, 5);
const basisY = segment(point(0, 0), point(0, 1), ORANGE, 5);
scene.add(original, mapped, basisX, basisY);

let readout = new Text({ text: 'det = area factor = 2.00', color: YELLOW, fontSize: 28 });
readout.moveTo([-2.8, -3.22, 0]);
scene.add(readout);

function update(amount) {
  t = amount;
  for (const item of grid) item.line.setVertices([point(item.a[0], item.a[1]), point(item.b[0], item.b[1])]);
  mapped.setVertices([point(0, 0), point(1, 0), point(1, 1), point(0, 1)]);
  basisX.setVertices([point(0, 0), point(1, 0)]);
  basisY.setVertices([point(0, 0), point(0, 1)]);
  scene.remove(readout);
  readout = new Text({ text: 'det = area factor = ' + (1 + t).toFixed(2), color: YELLOW, fontSize: 28 });
  readout.moveTo([-2.8, -3.22, 0]);
  scene.add(readout);
}

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Transformation', min: 0, max: 1, value: 1, step: 0.01, onChange: update });
